css:
.container {
  width: 100%;
  height: 100%;
  background: 
/* Deep ocean-like swirl base */
    radial-gradient(circle at 50% 50%, rgb(23, 32, 105), rgb(8, 12, 45)),
    /* Main conic spiral (multicolor infinity effect) */
      repeating-conic-gradient(
        from 45deg,
        #ec4899 0deg 15deg,
        #f59e0b 15deg 30deg,
        #10b981 30deg 45deg,
        #3b82f6 45deg 60deg,
        #8b5cf6 60deg 75deg,
        transparent 75deg 90deg
      ),
    /* Subtle 3D radial grid (blended softly) */
      repeating-radial-gradient(
        circle at center,
        rgba(255, 255, 255, 0.06) 0,
        rgba(255, 255, 255, 0.08) 2px,
        transparent 2px,
        transparent 5px
      ),
    /* Diamond-grid overlay (for depth) */
      linear-gradient(
        45deg,
        transparent 48%,
        rgba(255, 255, 255, 0.05) 48%,
        rgba(255, 255, 255, 0.05) 52%,
        transparent 52%
      ),
    linear-gradient(
      -45deg,
      transparent 48%,
      rgba(255, 255, 255, 0.05) 48%,
      rgba(255, 255, 255, 0.05) 52%,
      transparent 52%
    );

  background-size:
    100% 100%,
    /* Base gradient fills container */ 300px 300px,
    /* Conic spiral size (bigger = smoother) */ 150px 150px,
    /* Radial grid size */ 20px 20px,
    /* Diamond-grid size */ 20px 20px; /* Diamond-grid size */

  background-blend-mode:
    overlay,
    /* Blend conic spiral softly */ screen,
    /* Soft glow effect */ overlay,
    /* Enhance radial grid contrast */ normal; /* Diamond grid as subtle overlay */
}
